package io.github.mikeceead.xbscompanion;
import org.junit.Test;import java.util.*;import static org.junit.Assert.*;
public final class TaskerRequestPolicyTest{
 private Map<String,String> base(){Map<String,String> m=new LinkedHashMap<>();m.put(TaskerRequestPolicy.KEY_VERSION,"2");m.put(TaskerRequestPolicy.KEY_HOST_PACKAGE,TaskerHostIdentity.TASKER);m.put(TaskerRequestPolicy.KEY_HOST_CERT,String.join("",Collections.nCopies(64,"a")));m.put(TaskerRequestPolicy.KEY_NONCE,"abcdefghijklmnop");m.put(TaskerProtocol.KEY_MODULE,"xbs");m.put(TaskerProtocol.KEY_CLI_COMMAND,"status");m.put(TaskerProtocol.KEY_CLI_VALUES,"{}");m.put(TaskerProtocol.KEY_BACKEND,"root");m.put(TaskerRequestPolicy.KEY_ALLOW_DESTRUCTIVE,"false");return m;}
 @Test public void signedConfigurationRoundTripsAndTamperingFails(){byte[] key=new byte[32];Arrays.fill(key,(byte)7);Map<String,String> m=base();m.put(TaskerRequestPolicy.KEY_SIGNATURE,TaskerRequestPolicy.sign(m,key));assertTrue(TaskerRequestPolicy.verify(m,TaskerRequestPolicy.actionKeys(),key).valid);m.put(TaskerProtocol.KEY_CLI_COMMAND,"runtime_pause");assertEquals("bad_signature",TaskerRequestPolicy.verify(m,TaskerRequestPolicy.actionKeys(),key).code);}
 @Test public void unknownKeysAndOversizedValuesAreRejected(){Map<String,String> m=base();m.put("evil","x");assertEquals("unknown_key",TaskerRequestPolicy.validateAction(m,Collections.emptySet(),false).code);m=base();m.put(TaskerProtocol.KEY_CLI_VALUES,String.join("",Collections.nCopies(9000,"x")));assertEquals("value_too_large",TaskerRequestPolicy.validateAction(m,Collections.emptySet(),false).code);}
 @Test public void destructiveCommandsNeedExplicitSignedOptIn(){Map<String,String> m=base();assertEquals("destructive_opt_in_required",TaskerRequestPolicy.validateAction(m,Collections.emptySet(),true).code);m.put(TaskerRequestPolicy.KEY_ALLOW_DESTRUCTIVE,"true");assertTrue(TaskerRequestPolicy.validateAction(m,Collections.emptySet(),true).valid);}
 @Test public void whitespaceChangesAreBoundBySignature(){byte[] key=new byte[32];Arrays.fill(key,(byte)9);Map<String,String>m=base();m.put(TaskerProtocol.KEY_CLI_VALUES,"{\"event\":\" manual \"}");String sig=TaskerRequestPolicy.sign(m,key);m.put(TaskerProtocol.KEY_CLI_VALUES,"{\"event\":\"manual\"}");assertNotEquals(sig,TaskerRequestPolicy.sign(m,key));}
 @Test public void semanticProtocolFieldsAreRestricted(){Map<String,String>m=base();m.put(TaskerProtocol.KEY_MODULE,"other");assertEquals("invalid_module",TaskerRequestPolicy.validateAction(m,Collections.emptySet(),false).code);m=base();m.put(TaskerProtocol.KEY_BACKEND,"shell");assertEquals("invalid_backend",TaskerRequestPolicy.validateAction(m,Collections.emptySet(),false).code);}
 @Test public void canonicalizationIsStableAcrossMapOrder(){Map<String,String>a=base(),b=new LinkedHashMap<>();List<String>k=new ArrayList<>(a.keySet());Collections.reverse(k);for(String x:k)b.put(x,a.get(x));assertEquals(TaskerRequestPolicy.canonical(a),TaskerRequestPolicy.canonical(b));}
 @Test public void taskerVariableReplacementMetadataIsRejected(){Map<String,String>m=base();m.put("net.dinglisch.android.tasker.extras.VARIABLE_REPLACE_KEYS","cli_values");assertEquals("unknown_key",TaskerRequestPolicy.validateAction(m,Collections.emptySet(),false).code);}
 @Test public void conditionKindsAndStatesAreStrict(){Map<String,String>m=new LinkedHashMap<>();m.put(TaskerRequestPolicy.KEY_VERSION,"2");m.put(TaskerRequestPolicy.KEY_HOST_PACKAGE,TaskerHostIdentity.TASKER);m.put(TaskerRequestPolicy.KEY_HOST_CERT,String.join("",Collections.nCopies(64,"a")));m.put(TaskerRequestPolicy.KEY_NONCE,"abcdefghijklmnop");m.put(TaskerConditionProtocol.KEY_KIND,TaskerConditionProtocol.KIND_STATE);m.put(TaskerConditionProtocol.KEY_STATE,"evil");m.put(TaskerConditionProtocol.KEY_FILTER,"");assertEquals("invalid_runtime_state",TaskerRequestPolicy.validateCondition(m).code);}
}
